node -e "
const toRad = d => d * Math.PI / 180;

// Device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Shipping address: Boston, MA 02118 (approximate geocode)
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const R_km = 6371.0;
const R_mi = 3958.8;

const dist_km = (R_km * c).toFixed(1);
const dist_mi = (R_mi * c).toFixed(1);

console.log('=== Distance Calculation ===');
console.log('');
console.log('From (Device Location):');
console.log('  San Francisco, CA');
console.log('  Latitude:  37.7749° N');
console.log('  Longitude: 122.4194° W');
console.log('');
console.log('To (Order #W4705780 Shipping Address):');
console.log('  4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('  Latitude:  42.3388° N  (approx.)');
console.log('  Longitude: 71.0726° W  (approx.)');
console.log('');
console.log('=== Results (Straight-Line / As the Crow Flies) ===');
console.log('  ' + Number(dist_km).toLocaleString() + ' km');
console.log('  ' + Number(dist_mi).toLocaleString() + ' miles');
"
